import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against known values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - department is parameterized but sort column is dynamic
        String baseQuery = getBaseQuery(reportType);
        String query = baseQuery + " WHERE e.department = ? AND e.hire_date BETWEEN ? AND ?";

        // Sort column injection point - developer assumed limited UI dropdown
        if (sortCol != null && !sortCol.isEmpty()) {
            query += " ORDER BY " + sortCol;
        }

        log.info("Executing report query for dept=" + department + " sort=" + sortCol);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, department);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("headcount") ||
               type.equals("compensation") || type.equals("tenure"));
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("\\d{4}-\\d{2}-\\d{2}");
    }

    private String getBaseQuery(String reportType) {
        switch (reportType) {
            case "headcount":
                return "SELECT e.emp_id, e.name, e.department, e.hire_date FROM employees e";
            case "compensation":
                return "SELECT e.emp_id, e.name, e.department, e.salary, e.bonus FROM employees e";
            case "tenure":
                return "SELECT e.emp_id, e.name, e.department, e.hire_date, e.termination_date FROM employees e";
            default:
                return "SELECT e.emp_id, e.name FROM employees e";
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
